from abc import ABC, abstractmethod


class DataProcessorInterface(ABC):
    @abstractmethod
    def process(self, data):
        pass


class RealDataProcessor(DataProcessorInterface):
    def __init__(self, config):
        self.config = config

    def process(self, data):
        result = []
        for item in data:
            if self.config.get('filter'):
                if not self.config['filter'](item):
                    continue
            transformed = item
            if self.config.get('transform'):
                transformed = self.config['transform'](item)
            result.append(transformed)
        return result


class DataProcessorProxy(DataProcessorInterface):
    def __init__(self, config, authorized=True):
        self._processor = RealDataProcessor(config)
        self._authorized = authorized
        self._cache = None
        self._cached_data_id = None

    def process(self, data):
        if not self._authorized:
            raise PermissionError("Not authorized to process data")

        data_id = id(data)
        if self._cached_data_id == data_id and self._cache is not None:
            return self._cache

        result = self._processor.process(data)
        self._cache = result
        self._cached_data_id = data_id
        return result

from abc import ABC, abstractmethod
from typing import Any, Callable


class DataProcessorInterface(ABC):
    @abstractmethod
    def process(self, data: list[Any]) -> list[Any]:
        pass


class RealDataProcessor(DataProcessorInterface):
    def __init__(self, config: dict[str, Callable | None]) -> None:
        self.config = config

    def process(self, data: list[Any]) -> list[Any]:
        result: list[Any] = []
        for item in data:
            if self.config.get('filter'):
                if not self.config['filter'](item):
                    continue
            transformed: Any = item
            if self.config.get('transform'):
                transformed = self.config['transform'](item)
            result.append(transformed)
        return result


class DataProcessorProxy(DataProcessorInterface):
    def __init__(self, config: dict[str, Callable | None], authorized: bool = True) -> None:
        self._processor = RealDataProcessor(config)
        self._authorized = authorized
        self._cache: list[Any] | None = None
        self._cached_data_id: int | None = None

    def process(self, data: list[Any]) -> list[Any]:
        if not self._authorized:
            raise PermissionError("Not authorized to process data")

        data_id = id(data)
        if self._cached_data_id == data_id and self._cache is not None:
            return self._cache

        result = self._processor.process(data)
        self._cache = result
        self._cached_data_id = data_id
        return result

